import { Chess, type Move } from 'chess.js';
import { newId } from '../util/id';

export const START_FEN = 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';

/**
 * Where a move came from.
 * - historical: part of the game that was actually played (immutable)
 * - imported:   a variation that was present in an imported PGN
 * - user:       a hypothetical move the user explored
 * - engine:     a move generated by Stockfish while exploring
 */
/** 'theory' = a catalogued continuation added from the opening reference */
export type MoveSource = 'historical' | 'imported' | 'user' | 'engine' | 'theory';

export interface TreeNode {
  id: string;
  parentId: string | null;
  children: string[];
  /** ply number of the move that led to this node (root = 0) */
  ply: number;
  san: string | null;
  uci: string | null;
  /** position after the move */
  fen: string;
  source: MoveSource | 'root';
  comment?: string;
  nags?: number[];
  /** Name/notes for the branch that starts at this node (user-created branches). */
  branchName?: string;
  branchNote?: string;
  /** Clock remaining after the move in seconds (from PGN [%clk] or live play). */
  clock?: number;
  createdAt: number;
}

export interface GameTree {
  rootId: string;
  nodes: Record<string, TreeNode>;
}

export function createTree(startFen: string = START_FEN): GameTree {
  const rootId = newId('n');
  return {
    rootId,
    nodes: {
      [rootId]: { id: rootId, parentId: null, children: [], ply: plyFromFen(startFen), san: null, uci: null, fen: startFen, source: 'root', createdAt: Date.now() },
    },
  };
}

export function moveToUci(m: Pick<Move, 'from' | 'to' | 'promotion'>): string {
  return m.from + m.to + (m.promotion ?? '');
}

export function uciToMoveObj(uci: string): { from: string; to: string; promotion?: string } {
  return { from: uci.slice(0, 2), to: uci.slice(2, 4), promotion: uci.length > 4 ? uci[4] : undefined };
}

export function plyFromFen(fen: string): number {
  const parts = fen.split(' ');
  const full = parseInt(parts[5] ?? '1', 10) || 1;
  return (full - 1) * 2 + (parts[1] === 'b' ? 1 : 0);
}

/** Apply a move (SAN or {from,to,promotion} or UCI) to a FEN. Throws on illegal moves. */
export function applyMove(fen: string, move: string | { from: string; to: string; promotion?: string }): { move: Move; fen: string } {
  const c = new Chess(fen);
  let mv: Move;
  if (typeof move === 'string' && /^[a-h][1-8][a-h][1-8][qrbn]?$/.test(move)) {
    mv = c.move(uciToMoveObj(move));
  } else {
    mv = c.move(move as string);
  }
  return { move: mv, fen: c.fen() };
}

/**
 * Add a move below `parentId`. If an identical move already exists as a child the
 * existing node is returned (no duplicate branches). The tree is treated as
 * immutable: a new tree object is returned. Historical nodes are never modified.
 */
export function addMove(
  tree: GameTree,
  parentId: string,
  move: string | { from: string; to: string; promotion?: string },
  source: MoveSource,
  extra: Partial<Pick<TreeNode, 'comment' | 'nags' | 'clock'>> = {},
): { tree: GameTree; nodeId: string; existed: boolean } {
  const parent = tree.nodes[parentId];
  if (!parent) throw new Error(`Unknown node ${parentId}`);
  const { move: mv, fen } = applyMove(parent.fen, move);
  const uci = moveToUci(mv);
  const existing = parent.children.find((id) => tree.nodes[id].uci === uci);
  if (existing) return { tree, nodeId: existing, existed: true };
  const id = newId('n');
  const node: TreeNode = {
    id,
    parentId,
    children: [],
    ply: parent.ply + 1,
    san: mv.san,
    uci,
    fen,
    source,
    createdAt: Date.now(),
    ...extra,
  };
  const nodes = { ...tree.nodes, [id]: node, [parentId]: { ...parent, children: [...parent.children, id] } };
  return { tree: { ...tree, nodes }, nodeId: id, existed: false };
}

/** Path of node ids from root (inclusive) to nodeId (inclusive). */
export function pathTo(tree: GameTree, nodeId: string): string[] {
  const path: string[] = [];
  let cur: string | null = nodeId;
  while (cur) {
    path.push(cur);
    cur = tree.nodes[cur]?.parentId ?? null;
  }
  return path.reverse();
}

/** The historical (actually played) line: root followed by historical children. */
export function mainline(tree: GameTree): string[] {
  const line = [tree.rootId];
  let cur = tree.nodes[tree.rootId];
  for (;;) {
    const next = cur.children.find((id) => tree.nodes[id].source === 'historical');
    if (!next) break;
    line.push(next);
    cur = tree.nodes[next];
  }
  return line;
}

/** Follow first children from nodeId to the end of its line. */
export function lineFrom(tree: GameTree, nodeId: string): string[] {
  const line = [nodeId];
  let cur = tree.nodes[nodeId];
  while (cur.children.length) {
    // Prefer historical child if present, otherwise the first-created child.
    const next = cur.children.find((id) => tree.nodes[id].source === 'historical') ?? cur.children[0];
    line.push(next);
    cur = tree.nodes[next];
  }
  return line;
}

export function isHistorical(tree: GameTree, nodeId: string): boolean {
  const n = tree.nodes[nodeId];
  return n.source === 'historical' || n.source === 'root';
}

/**
 * Delete a non-historical node and its entire subtree. Historical nodes (the
 * original game) can never be deleted.
 */
export function deleteBranch(tree: GameTree, nodeId: string): GameTree {
  const node = tree.nodes[nodeId];
  if (!node || isHistorical(tree, nodeId)) throw new Error('The original game cannot be deleted.');
  const nodes = { ...tree.nodes };
  const stack = [nodeId];
  while (stack.length) {
    const id = stack.pop()!;
    stack.push(...nodes[id].children);
    delete nodes[id];
  }
  const parent = nodes[node.parentId!];
  nodes[parent.id] = { ...parent, children: parent.children.filter((c) => c !== nodeId) };
  return { ...tree, nodes };
}

export function updateNode(tree: GameTree, nodeId: string, patch: Partial<Pick<TreeNode, 'comment' | 'branchName' | 'branchNote' | 'nags'>>): GameTree {
  const node = tree.nodes[nodeId];
  if (!node) throw new Error(`Unknown node ${nodeId}`);
  if (node.source === 'historical' && ('branchName' in patch || 'branchNote' in patch)) {
    throw new Error('Branch names belong to explored variations, not the original game.');
  }
  return { ...tree, nodes: { ...tree.nodes, [nodeId]: { ...node, ...patch } } };
}

/** Preferred continuation of a node: its historical child, otherwise its first child. */
export function preferredChild(tree: GameTree, nodeId: string): string | null {
  const n = tree.nodes[nodeId];
  return n.children.find((c) => tree.nodes[c].source === 'historical') ?? n.children[0] ?? null;
}

/** True if this node begins a variation (it is not its parent's preferred continuation, or it leaves the original game). */
export function startsBranch(tree: GameTree, nodeId: string): boolean {
  const n = tree.nodes[nodeId];
  if (!n.parentId || n.source === 'historical') return false;
  const parent = tree.nodes[n.parentId];
  if (parent.source === 'historical' || parent.source === 'root') return true;
  return preferredChild(tree, parent.id) !== nodeId;
}

/** The node that starts the variation containing nodeId, or null if nodeId is on the original game. */
export function branchStart(tree: GameTree, nodeId: string): string | null {
  let cur: TreeNode | undefined = tree.nodes[nodeId];
  while (cur && cur.parentId) {
    if (startsBranch(tree, cur.id)) return cur.id;
    cur = tree.nodes[cur.parentId];
  }
  return null;
}

export function countBranches(tree: GameTree): number {
  return Object.keys(tree.nodes).filter((id) => startsBranch(tree, id)).length;
}

/** Build a tree whose mainline is the given SAN list (historical). */
export function treeFromMoves(sans: string[], startFen: string = START_FEN, source: MoveSource = 'historical'): GameTree {
  let tree = createTree(startFen);
  let cur = tree.rootId;
  for (const san of sans) {
    const r = addMove(tree, cur, san, source);
    tree = r.tree;
    cur = r.nodeId;
  }
  return tree;
}

export function sansOnPath(tree: GameTree, path: string[]): string[] {
  return path.slice(1).map((id) => tree.nodes[id].san!);
}

export function moveNumberLabel(ply: number): string {
  // ply is the ply of the move (1 = white's first move, 2 = black's first move)
  const n = Math.ceil(ply / 2);
  return ply % 2 === 1 ? `${n}.` : `${n}...`;
}
